css:
.fc-label { font: 400 30px/1.15 var(--font-body); color: var(--ink); letter-spacing: 0; text-transform: lowercase; white-space: nowrap; }
.fc-label.on-dark { color: #fff; }
.fc-name { font: 400 64px/1 var(--font-display); color: var(--ink); letter-spacing: -0.01em; text-transform: lowercase; }
.fc-rule { position: absolute; background: currentColor; }
